package local.cleartv.mobile;
import android.content.Context;import java.net.*;import java.io.*;import org.json.*;
final class AndroidTv {
 static final int[] PORTS={8787,8789,8790};static final java.util.concurrent.ConcurrentHashMap<String,Integer> ports=new java.util.concurrent.ConcurrentHashMap<>();
 static JSONObject request(String ip,String route,JSONObject body,String token)throws Exception{try{if(!ports.containsKey(ip))probe(ip);return once(ip,route,body,token);}catch(java.net.ConnectException|java.net.SocketTimeoutException e){if(body==null){try{ports.remove(ip);probe(ip);return once(ip,route,null,token);}catch(java.net.ConnectException|java.net.SocketTimeoutException ignored){}}throw new IOException("تعذّر الوصول إلى Morph TV على "+ip+". افتح التطبيق على التلفزيون وتأكد أن عنوان IP لم يتغير من صفحة ربط الموبايل، وأن الجهازين على نفس Wi-Fi. لا تحتاج لإعادة تثبيت التطبيق.");}}
 static JSONObject once(String ip,String route,JSONObject body,String token)throws Exception{
  return onceAt(ip,ports.getOrDefault(ip,8787),route,body,token,false);
 }
 static JSONObject onceAt(String ip,int port,String route,JSONObject body,String token,boolean probe)throws Exception{
  if(!Network.local(ip))throw new IOException("اكتب عنوان التلفزيون على الشبكة المحلية.");HttpURLConnection c=(HttpURLConnection)new URL("http://"+ip+":"+port+route).openConnection();c.setConnectTimeout(probe?900:4000);c.setReadTimeout(probe?1500:route.startsWith("/iptv/")?30000:12000);c.setInstanceFollowRedirects(false);
  try{if(token!=null)c.setRequestProperty("X-TV-Morph-Token",token);if(body!=null){c.setRequestMethod("POST");c.setRequestProperty("Content-Type","application/json");c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}
   int code=c.getResponseCode();if(code==401)throw new IOException("الربط محتاج يتجدد. افتح Morph TV على التلفزيون واكتب كود الربط الجديد.");if(code!=200)throw new IOException(code==429?"محاولات ربط كتير. انتظر دقيقة وافتح كود جديد من التلفزيون.":"التلفزيون لم يقبل الطلب. تأكد من الكود ومن فتح التطبيق.");return new JSONObject(new String(Network.read(c.getInputStream(),1024*1024),"UTF-8"));
  }finally{c.disconnect();}
 }
 static JSONObject probe(String ip)throws Exception{if(!Network.local(ip))throw new IOException("Invalid local address");JSONObject d=null;int selected=0;long highest=-1;for(int port:PORTS){try{JSONObject info=onceAt(ip,port,"/info",null,null,true);if(!info.optString("service").equals("tv-morph-android"))continue;long score=0;String[] version=info.optString("version","0.0.0").split("[-+]")[0].split("\\.");for(int i=0;i<3;i++)score=score*10000+(i<version.length?Integer.parseInt(version[i]):0);if(d==null||score>highest){d=info;selected=port;highest=score;}}catch(Exception ignored){}}if(d==null)throw new IOException("Morph TV غير متاح على العنوان ده. افتح التطبيق على الشاشة وتأكد من نفس الشبكة.");ports.put(ip,selected);return new JSONObject().put("ip",ip).put("brand","android").put("fireTV",d.optString("model").startsWith("AFT")||d.optString("name").toLowerCase(java.util.Locale.US).contains("amazon")).put("name",d.optString("name","Android TV")).put("model",d.optString("model")).put("os",d.optString("os")).put("developerReady",false).put("hint","التطبيق موجود. أدخل كود الربط الظاهر على التلفزيون.");}
 static String token(Context c,String ip)throws Exception{byte[] bytes=new Vault(c).get("android-"+ip.replace('.','_'));if(bytes==null)throw new IOException("اربط التلفزيون بكود الشاشة الأول.");return new String(bytes,"UTF-8");}
 static void pair(Context c,String ip,String code)throws Exception{if(!code.matches("[0-9]{6}"))throw new IOException("كود الربط ٦ أرقام من شاشة التلفزيون.");JSONObject r=request(ip,"/pair",new JSONObject().put("code",code),null);String key=r.getString("token");if(!key.matches("[a-f0-9]{64}"))throw new IOException("Invalid pairing response");new Vault(c).put("android-"+ip.replace('.','_'),key.getBytes("UTF-8"));}
}
